import{_ as d,c as e,o,ae as c}from"./chunks/framework.CDjunVez.js";const p=JSON.parse('{"title":"Linux 常用命令速查 (Cheat Sheet)","description":"","frontmatter":{},"headers":[],"relativePath":"linux.md","filePath":"linux.md"}'),r={name:"linux.md"};function a(h,t,l,i,s,n){return o(),e("div",null,[...t[0]||(t[0]=[c('<h1 id="linux-常用命令速查-cheat-sheet" tabindex="-1">Linux 常用命令速查 (Cheat Sheet) <a class="header-anchor" href="#linux-常用命令速查-cheat-sheet" aria-label="Permalink to &quot;Linux 常用命令速查 (Cheat Sheet)&quot;">​</a></h1><p>本文档汇总了日常运维和开发中最常用的 Linux 命令，涵盖文件操作、系统监控、网络管理、运维等领域。</p><h2 id="_1-文件与目录操作" tabindex="-1">1. 文件与目录操作 <a class="header-anchor" href="#_1-文件与目录操作" aria-label="Permalink to &quot;1. 文件与目录操作&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><code>ls</code></td><td>列出目录内容</td><td><code>ls -ll</code> (详细列表), <code>ls -a</code> (显示隐藏文件)</td></tr><tr><td><code>cd</code></td><td>切换目录</td><td><code>cd /home</code> (去指定目录), <code>cd ..</code> (返回上一级)</td></tr><tr><td><code>pwd</code></td><td>显示当前工作目录</td><td><code>pwd</code></td></tr><tr><td><code>mkdir</code></td><td>创建目录</td><td><code>mkdir code</code> (创建单个), <code>mkdir -p a/b/c</code> (递归创建)</td></tr><tr><td><code>rm</code></td><td>删除文件或目录</td><td><code>rm file.txt</code> (删文件), <code>rm -rf dir/</code> (强制递归删目录)</td></tr><tr><td><code>cp</code></td><td>复制</td><td><code>cp file1 file2</code> (复制文件), <code>cp -r dir1 dir2</code> (复制目录)</td></tr><tr><td><code>mv</code></td><td>移动或重命名</td><td><code>mv old.txt new.txt</code> (重命名), <code>mv file dir/</code> (移动)</td></tr><tr><td><code>touch</code></td><td>创建空文件或更新时间戳</td><td><code>touch index.html</code></td></tr><tr><td><code>find</code></td><td>查找文件</td><td><code>find / -name &quot;*.log&quot;</code> (全盘查找 log 文件)</td></tr></tbody></table><h2 id="_2-文件查看与编辑" tabindex="-1">2. 文件查看与编辑 <a class="header-anchor" href="#_2-文件查看与编辑" aria-label="Permalink to &quot;2. 文件查看与编辑&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><code>cat</code></td><td>查看文件全部内容</td><td><code>cat config.json</code></td></tr><tr><td><code>tail</code></td><td>查看文件尾部 (常用于看日志)</td><td><code>tail -f app.log</code> (实时追踪日志变化)</td></tr><tr><td><code>less</code></td><td>分页查看大文件</td><td><code>less large.log</code> (按 q 退出)</td></tr><tr><td><code>grep</code></td><td>文本搜索/过滤</td><td><code>grep &quot;error&quot; app.log</code> (查找包含 error 的行)</td></tr><tr><td><code>vim</code> / <code>nano</code></td><td>文本编辑器</td><td><code>vim server.py</code></td></tr></tbody></table><h2 id="_3-用户与权限管理" tabindex="-1">3. 用户与权限管理 <a class="header-anchor" href="#_3-用户与权限管理" aria-label="Permalink to &quot;3. 用户与权限管理&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><code>sudo</code></td><td>以管理员身份执行</td><td><code>sudo apt update</code></td></tr><tr><td><code>chmod</code></td><td>修改文件权限</td><td><code>chmod +x script.sh</code> (添加执行权限), <code>chmod 777 file</code></td></tr><tr><td><code>chown</code></td><td>修改文件所有者</td><td><code>chown user:group file</code></td></tr><tr><td><code>useradd</code></td><td>添加新用户</td><td><code>useradd -m username</code></td></tr><tr><td><code>passwd</code></td><td>修改密码</td><td><code>passwd username</code></td></tr><tr><td><code>su</code></td><td>切换用户</td><td><code>su - username</code></td></tr></tbody></table><h2 id="_4-系统管理-进程监控" tabindex="-1">4. 系统管理 &amp; 进程监控 <a class="header-anchor" href="#_4-系统管理-进程监控" aria-label="Permalink to &quot;4. 系统管理 &amp; 进程监控&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><code>top</code> / <code>htop</code></td><td>实时查看系统资源与进程</td><td><code>top</code> (按 q 退出)</td></tr><tr><td><code>ps</code></td><td>查看静态进程快照</td><td>`ps aux</td></tr><tr><td><code>kill</code></td><td>终止进程</td><td><code>kill 1234</code> (杀掉 PID 为 1234 的进程)</td></tr><tr><td><code>killall</code></td><td>根据名称终止进程</td><td><code>killall nginx</code></td></tr><tr><td><code>systemctl</code></td><td>管理后台服务</td><td><code>systemctl restart docker</code></td></tr><tr><td><code>df</code></td><td>查看磁盘空间</td><td><code>df -h</code> (以易读格式显示)</td></tr><tr><td><code>free</code></td><td>查看内存使用</td><td><code>free -h</code></td></tr><tr><td><code>history</code></td><td>查看历史命令</td><td>`history</td></tr></tbody></table><h2 id="_5-网络操作" tabindex="-1">5. 网络操作 <a class="header-anchor" href="#_5-网络操作" aria-label="Permalink to &quot;5. 网络操作&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><code>ip addr</code></td><td>查看 IP 地址</td><td><code>ip a</code></td></tr><tr><td><code>ping</code></td><td>测试网络连通性</td><td><code>ping google.com</code></td></tr><tr><td><code>curl</code></td><td>发送 HTTP 请求</td><td><code>curl -I baidu.com</code> (查看响应头)</td></tr><tr><td><code>netstat</code></td><td>查看网络端口占用</td><td>`netstat -tulpn</td></tr><tr><td><code>ssh</code></td><td>远程登录</td><td><code>ssh user@192.168.1.1</code></td></tr><tr><td><code>scp</code></td><td>远程文件传输</td><td><code>scp local_file user@server:/path</code></td></tr></tbody></table><h2 id="_6-压缩与解压" tabindex="-1">6. 压缩与解压 <a class="header-anchor" href="#_6-压缩与解压" aria-label="Permalink to &quot;6. 压缩与解压&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><code>tar</code> (打包/解压)</td><td>Linux 最常用格式</td><td><strong>解压:</strong> <code>tar -zxvf data.tar.gz</code><br></td></tr></tbody></table><p><br><strong>压缩:</strong> <code>tar -czvf data.tar.gz folder/</code> | | <code>zip</code> / <code>unzip</code> | Windows 常用格式 | <code>unzip file.zip</code> |</p><hr><blockquote><p><strong>💡 小技巧：</strong></p><ul><li><strong>Tab 键：</strong> 自动补全文件名或命令，按两下显示所有匹配项。</li><li><strong>Ctrl + C：</strong> 强制停止当前正在运行的命令。</li><li><strong>Ctrl + L：</strong> 清屏 (相当于 <code>clear</code> 命令)。</li></ul></blockquote>',17)])])}const b=d(r,[["render",a]]);export{p as __pageData,b as default};
